 travel(i){const l=LOCATIONS[i];this.location=l;this.p.set(l.x,l.y+.25,l.z+(l.type==='city'?5:l.type==='lake'?35:l.type==='woods'?58:9));if(l.type==='mine')this.p.set(l.x,26.9,l.z);this.p.y=this.world.ground(this.p.x,this.p.z,l.type==='mine'?this.p.y+1:Math.max(l.y+10,this.p.y),.5)+.04;for(let tries=0;tries<20&&this.world.blocked(this.p.x,this.p.z,this.p.y);tries++){this.p.z+=2;this.p.y=this.world.ground(this.p.x,this.p.z,l.y+10,.5)+.04;}this.player.velY=0;this.player.onGround=true;this.yaw=0;this.pitch=.12;this.glider.visible=false;this.state='playing';this.avatar.root.position.copy(this.p);this.locTimer=4;$('location-banner').innerHTML=`<small>ENTERED</small>${l.name.toUpperCase()}`;}
