 updateAction(dt){if(!this.action)return;const a=this.action;a.remaining-=dt;if(a.kind==='chest'&&Math.hypot(this.p.x-a.target.x,this.p.z-a.target.z)>3.6){this.action=null;return;}if(a.remaining>0)return;if(a.kind==='reload'){const it=this.player.inventory[a.slot];if(it){const w=WEAPONS[it.type],n=Math.min(w.mag-it.rounds,this.player.ammo[w.ammo]);it.rounds+=n;this.player.ammo[w.ammo]-=n;this.sound.play('reload');}}
 if(a.kind==='heal'){const it=this.player.inventory[a.slot];if(it){const w=WEAPONS[it.type];if(w.both){this.player.shield=this.player.health=100;}else if(w.health)this.player.health=Math.min(w.limit,this.player.health+w.heal);else this.player.shield=Math.min(w.limit,this.player.shield+w.heal);it.count--;if(it.count<=0){this.player.inventory[a.slot]=null;this.equip(0);}this.sound.play('shield');}}
 if(a.kind==='chest'&&!a.target.opened){this.world.openChest(a.target);this.player.chests++;for(const k of ['medium','light'])this.player.ammo[k]+=18;this.player.ammo.shells+=8;this.player.materials.wood=Math.min(999,this.player.materials.wood+30);this.sound.play('chest');this.ui.notify('Chest searched · ammunition and materials collected');}this.action=null;}
