 const type=this.weaponType(),w=WEAPONS[type];if(w.heal){this.useItem();return;}if(type==='pickaxe'){this.swing=w.rate;this.harvestImpact=w.rate*.46;this.sound.play('pickaxe');this.cooldown=w.rate;return;}const it=this.player.inventory[this.player.slot-1];if(!it?.rounds){this.reload();if(!this.player.ammo[w.ammo])this.ui.notify('Not enough ammo');return;}it.rounds--;this.cooldown=w.rate;this.player.shots++;this.recoil+=.018;this.sound.play('shoot',type);const dir=this.viewDirection();const eye=this.render.camera.position;const target=eye.clone().addScaledVector(dir,w.range);const muzzle=this.p.clone().add(new T.Vector3(.2,1.36,0)).addScaledVector(dir,.55);const aim=this.findHit(eye,dir,w.range,true);if(aim)target.copy(eye).addScaledVector(dir,aim.distance);const base=target.clone().sub(muzzle).normalize();
